    ('1f11ecff-7fc1-42e0-8bfd-cc8e52edcb31', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Dấu ngoặc kép dùng để đánh dấu lời dẫn trực tiếp. Theo em, nhận định trên đúng hay sai?', 'Dau ngoac kep dung de danh dau loi dan truc tiep. Theo em, nhan dinh tren dung hay sai?', 'Dấu ngoặc kép dùng để đánh dấu lời dẫn trực tiếp.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
