    ('f47cdb70-f982-49ba-b3f8-2f020a6eb8fb', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', '''Đất nước ngàn năm văn hiến'' chỉ nói về địa lý tự nhiên. Câu trên đúng hay sai?', '''Dat nuoc ngan nam van hien'' chi noi ve dia ly tu nhien. Cau tren dung hay sai?', '''Đất nước ngàn năm văn hiến'' ca ngợi truyền thống văn hóa lâu đời của dân tộc.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
