    ('fe2eb786-7e57-458a-b773-d47bd0868c0a', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong 4 phương án dưới đây, đâu là phương án đúng?', 'Trong 4 phuong an duoi day, dau la phuong an dung?', 'Bác Hồ là vị lãnh tụ vĩ đại, người đã tìm ra con đường cứu nước cho dân tộc Việt Nam.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('9be986cc-b629-4817-b21e-5fc3b8e296f6', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu ghép có quan hệ từ ''vì...nên'' thể hiện quan hệ tương phản. Câu trên đúng hay sai?', 'Cau ghep co quan he tu ''vi...nen'' the hien quan he tuong phan. Cau tren dung hay sai?', 'Câu ghép có quan hệ từ ''vì...nên'' thể hiện quan hệ nguyên nhân - kết quả.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('b8509be2-5587-4040-9fb6-518874ef050e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Hãy chỉ ra nhận định đúng trong các câu sau:', 'Hay chi ra nhan dinh dung trong cac cau sau:', 'Đại từ dùng để thay thế cho danh từ, tránh lặp lại từ ngữ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
