    ('849f1aaa-119a-4b3b-bb8d-f54c97d3611b', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đâu là nhận định đúng?', 'Dau la nhan dinh dung?', 'Bác Hồ là vị lãnh tụ vĩ đại, người đã tìm ra con đường cứu nước cho dân tộc Việt Nam.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('ea6ae1db-5b1a-4dcb-9af1-2668d5d29a25', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu ghép có quan hệ từ ''vì...nên'' thể hiện quan hệ nguyên nhân - kết quả. Câu trên đúng hay sai?', 'Cau ghep co quan he tu ''vi...nen'' the hien quan he nguyen nhan - ket qua. Cau tren dung hay sai?', 'Câu ghép có quan hệ từ ''vì...nên'' thể hiện quan hệ nguyên nhân - kết quả.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('24a4bc0f-a341-4a9c-83cc-9b0d8a4a0aae', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy viết đoạn văn tả người thân mà em yêu quý nhất.', 'Em hay viet doan van ta nguoi than ma em yeu quy nhat.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('3ff1d7f5-52b4-46c6-b439-009f2270148d', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đại từ dùng để chỉ đặc điểm, tính chất của sự vật. Theo em, nhận định trên đúng hay sai?', 'Dai tu dung de chi dac diem, tinh chat cua su vat. Theo em, nhan dinh tren dung hay sai?', 'Đại từ dùng để thay thế cho danh từ, tránh lặp lại từ ngữ.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('81d94e4b-9d38-47ff-8356-02927c89c501', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Phương án nào dưới đây là đúng?', 'Phuong an nao duoi day la dung?', 'Biện pháp so sánh giúp câu văn thêm sinh động, gợi hình.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('536041d3-6270-4ce2-a19d-f3cd435b74e9', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ca dao, tục ngữ là những sáng tác dân gian truyền miệng của nhân dân. Câu trên đúng hay sai?', 'Ca dao, tuc ngu la nhung sang tac dan gian truyen mieng cua nhan dan. Cau tren dung hay sai?', 'Ca dao, tục ngữ là những sáng tác dân gian truyền miệng của nhân dân.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('5dd0e42d-1dd1-4e4a-a89f-d939a367f2dc', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Ý nào sau đây phản ánh đúng nội dung đã học?', 'Y nao sau day phan anh dung noi dung da hoc?', 'Dấu ngoặc kép dùng để đánh dấu lời dẫn trực tiếp.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('f0da45b6-395e-4e4b-bc82-1914a2ffff33', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ đồng nghĩa là những từ có nghĩa trái ngược nhau. Theo em, nhận định trên đúng hay sai?', 'Tu dong nghia la nhung tu co nghia trai nguoc nhau. Theo em, nhan dinh tren dung hay sai?', 'Từ đồng nghĩa là những từ có nghĩa giống nhau hoặc gần giống nhau.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
