    ('5f66904a-b522-492e-bfa6-ce30056edb33', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy viết đoạn văn tả người thân mà em yêu quý nhất.', 'Em hay viet doan van ta nguoi than ma em yeu quy nhat.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('ebd6827b-b646-4cc5-b85e-f4d481c3d93f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ đồng nghĩa là những từ có nghĩa trái ngược nhau. Câu trên đúng hay sai?', 'Tu dong nghia la nhung tu co nghia trai nguoc nhau. Cau tren dung hay sai?', 'Từ đồng nghĩa là những từ có nghĩa giống nhau hoặc gần giống nhau.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('b8fee8be-1566-47c7-a94a-8c61be361ba0', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Trong các phát biểu sau, phát biểu nào đúng?', 'Trong cac phat bieu sau, phat bieu nao dung?', 'Từ trái nghĩa là những từ có nghĩa trái ngược nhau.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('4154cb0a-6b73-44c4-853d-1c8c56aecd8a', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'easy' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Quan hệ từ dùng để nối các từ ngữ hoặc các vế câu, ví dụ ''vì...nên''. Theo em, nhận định trên đúng hay sai?', 'Quan he tu dung de noi cac tu ngu hoac cac ve cau, vi du ''vi...nen''. Theo em, nhan dinh tren dung hay sai?', 'Quan hệ từ dùng để nối các từ ngữ hoặc các vế câu, ví dụ ''vì...nên''.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('58244509-2606-4daf-9de9-44897477e73c', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C1' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'remember' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Nhận định nào sau đây là chính xác?', 'Nhan dinh nao sau day la chinh xac?', '''Đất nước ngàn năm văn hiến'' ca ngợi truyền thống văn hóa lâu đời của dân tộc.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('5a2930b2-8127-4a76-870e-35728d8ec25e', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C2' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'understand' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Bài văn tả người chỉ cần nêu tên người đó. Câu trên đúng hay sai?', 'Bai van ta nguoi chi can neu ten nguoi do. Cau tren dung hay sai?', 'Bài văn tả người cần miêu tả ngoại hình, tính cách, hoạt động của người đó.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('61b78ca3-36e7-430b-8d03-6e4f5a989023', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'apply' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Chọn phát biểu đúng trong các phương án sau:', 'Chon phat bieu dung trong cac phuong an sau:', 'Bài văn tả cảnh thường miêu tả theo trình tự thời gian hoặc không gian.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('6c2ffe1a-331a-4090-a441-0ee2ccc55815', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Bác Hồ chỉ là một nhà thơ nổi tiếng, không liên quan đến cách mạng. Theo em, nhận định trên đúng hay sai?', 'Bac Ho chi la mot nha tho noi tieng, khong lien quan den cach mang. Theo em, nhan dinh tren dung hay sai?', 'Bác Hồ là vị lãnh tụ vĩ đại, người đã tìm ra con đường cứu nước cho dân tộc Việt Nam.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('8cc52d31-0a43-4700-a0f2-bc3092706fc1', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'multiple_choice' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'evaluate' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Đâu là nhận định đúng?', 'Dau la nhan dinh dung?', 'Câu ghép có quan hệ từ ''vì...nên'' thể hiện quan hệ nguyên nhân - kết quả.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
    ('75cb0e80-0868-45c6-aee6-ca22a81f645f', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C6' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'essay' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Em hãy viết đoạn văn tả cảnh buổi sáng ở quê hương hoặc nơi em sống.', 'Em hay viet doan van ta canh buoi sang o que huong hoac noi em song.', 'Câu hỏi tự luận — chấm theo rubric của giáo viên.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
