    ('c969f7b9-7350-4f45-a4dc-8058d3b6822c', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 5 AND code = 'VIE') AND code = 'C4' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'analyze' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Từ đồng nghĩa là những từ có nghĩa trái ngược nhau. Câu trên đúng hay sai?', 'Tu dong nghia la nhung tu co nghia trai nguoc nhau. Cau tren dung hay sai?', 'Từ đồng nghĩa là những từ có nghĩa giống nhau hoặc gần giống nhau.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 5']::TEXT[], true, true, 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
